import re

def evaluate(expr):
    tokens = re.findall(r'\d+|[+\-*/()]', expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        val = parse_unary()
        while peek() in ('*', '/'):
            op = consume()
            rhs = parse_unary()
            val = val * rhs if op == '*' else val / rhs
        return val

    def parse_unary():
        if peek() == '-':
            consume()
            return -parse_unary()
        if peek() == '+':
            consume()
            return parse_unary()
        return parse_atom()

    def parse_atom():
        tok = peek()
        if tok == '(':
            consume()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("missing )")
            consume()
            return val
        if tok is None or not tok.isdigit():
            raise ValueError(f"unexpected token: {tok}")
        return float(consume())

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError(f"unexpected token: {tokens[pos]}")
    return result
