def evaluate(expr):
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(float(expr[i:j]))
            i = j
        else:
            tokens.append(c)
            i += 1

    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def take():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = take()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = take()
            rhs = parse_factor()
            val = val * rhs if op == '*' else val / rhs
        return val

    def parse_factor():
        tok = peek()
        if tok == '-':
            take()
            return -parse_factor()
        if tok == '+':
            take()
            return parse_factor()
        if tok == '(':
            take()
            val = parse_expr()
            take()  # ')'
            return val
        return take()

    return float(parse_expr())
