class _Parser:
    def __init__(self, expr):
        self.expr = expr
        self.pos = 0

    def skip_ws(self):
        while self.pos < len(self.expr) and self.expr[self.pos].isspace():
            self.pos += 1

    def peek(self):
        self.skip_ws()
        if self.pos >= len(self.expr):
            return None
        return self.expr[self.pos]

    def consume(self, ch):
        self.skip_ws()
        if self.pos < len(self.expr) and self.expr[self.pos] == ch:
            self.pos += 1
            return True
        return False

    def parse_expression(self):
        value = self.parse_term()
        while True:
            ch = self.peek()
            if ch == '+':
                self.consume('+')
                value += self.parse_term()
            elif ch == '-':
                self.consume('-')
                value -= self.parse_term()
            else:
                break
        return value

    def parse_term(self):
        value = self.parse_factor()
        while True:
            ch = self.peek()
            if ch == '*':
                self.consume('*')
                value *= self.parse_factor()
            elif ch == '/':
                self.consume('/')
                value /= self.parse_factor()
            else:
                break
        return value

    def parse_factor(self):
        ch = self.peek()

        if ch == '+':
            self.consume('+')
            return self.parse_factor()

        if ch == '-':
            self.consume('-')
            return -self.parse_factor()

        if ch == '(':
            self.consume('(')
            value = self.parse_expression()
            if not self.consume(')'):
                raise ValueError("Missing closing parenthesis")
            return value

        if ch is not None and ch.isdigit():
            start = self.pos
            while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                self.pos += 1
            return float(self.expr[start:self.pos])

        raise ValueError("Invalid expression")

    def parse(self):
        if self.peek() is None:
            raise ValueError("Empty expression")
        value = self.parse_expression()
        if self.peek() is not None:
            raise ValueError("Unexpected character")
        return value


def evaluate(expr):
    return _Parser(expr).parse()
