def evaluate(expr):
    s = expr
    n = len(s)
    i = 0

    def skip_whitespace():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def parse_expression():
        nonlocal i
        value = parse_term()
        while True:
            skip_whitespace()
            if i < n and s[i] in "+-":
                op = s[i]
                i += 1
                rhs = parse_term()
                if op == "+":
                    value += rhs
                else:
                    value -= rhs
            else:
                break
        return value

    def parse_term():
        nonlocal i
        value = parse_factor()
        while True:
            skip_whitespace()
            if i < n and s[i] in "*/":
                op = s[i]
                i += 1
                rhs = parse_factor()
                if op == "*":
                    value *= rhs
                else:
                    value /= rhs
            else:
                break
        return value

    def parse_factor():
        nonlocal i
        skip_whitespace()
        if i < n and s[i] in "+-":
            op = s[i]
            i += 1
            value = parse_factor()
            return value if op == "+" else -value
        return parse_primary()

    def parse_primary():
        nonlocal i
        skip_whitespace()

        if i >= n:
            raise ValueError("Unexpected end of expression")

        if s[i] == "(":
            i += 1
            value = parse_expression()
            skip_whitespace()
            if i >= n or s[i] != ")":
                raise ValueError("Missing closing parenthesis")
            i += 1
            return value

        if s[i].isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return int(s[start:i])

        raise ValueError(f"Unexpected character: {s[i]!r}")

    skip_whitespace()
    if i >= n:
        raise ValueError("Empty expression")

    result = parse_expression()
    skip_whitespace()

    if i != n:
        raise ValueError(f"Unexpected character: {s[i]!r}")

    return float(result)
