class _Evaluator:
    def __init__(self, s):
        self.s = s
        self.pos = 0
        self.n = len(s)

    def parse(self):
        self._skip_ws()
        if self.pos >= self.n:
            raise ValueError("empty expression")

        value = self._expression()

        self._skip_ws()
        if self.pos != self.n:
            raise ValueError(f"unexpected character: {self.s[self.pos]!r}")
        return value

    def _skip_ws(self):
        while self.pos < self.n and self.s[self.pos].isspace():
            self.pos += 1

    def _peek(self):
        self._skip_ws()
        if self.pos < self.n:
            return self.s[self.pos]
        return ''

    def _expression(self):
        value = self._term()

        while True:
            c = self._peek()
            if c == '+':
                self.pos += 1
                value += self._term()
            elif c == '-':
                self.pos += 1
                value -= self._term()
            else:
                break

        return value

    def _term(self):
        value = self._factor()

        while True:
            c = self._peek()
            if c == '*':
                self.pos += 1
                value *= self._factor()
            elif c == '/':
                self.pos += 1
                value /= self._factor()
            else:
                break

        return value

    def _factor(self):
        c = self._peek()

        if c == '-':
            self.pos += 1
            return -self._factor()

        if c == '(':
            self.pos += 1
            value = self._expression()
            if self._peek() != ')':
                raise ValueError("mismatched parentheses")
            self.pos += 1
            return value

        if c.isdigit():
            start = self.pos
            while self.pos < self.n and self.s[self.pos].isdigit():
                self.pos += 1
            return float(self.s[start:self.pos])

        raise ValueError(f"unexpected character: {c!r}")
