def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression containing integers, + - * /,
    parentheses, and unary minus. Returns a float."""

    def tokenize(s):
        tokens = []
        i = 0

        while i < len(s):
            ch = s[i]

            if ch.isspace():
                i += 1

            elif "0" <= ch <= "9":
                start = i
                while i < len(s) and "0" <= s[i] <= "9":
                    i += 1
                tokens.append(("NUM", int(s[start:i])))

            elif ch in "+-*/()":
                tokens.append((ch, ch))
                i += 1

            else:
                raise ValueError(f"Invalid character {ch!r} at position {i}")

        return tokens

    tokens = tokenize(expr)

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos][0] if pos < len(tokens) else None

    def consume(expected=None):
        nonlocal pos

        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")

        kind, value = tokens[pos]

        if expected is not None and kind != expected:
            raise ValueError(f"Expected {expected!r}, got {kind!r}")

        pos += 1
        return kind, value

    def parse_expression():
        value = parse_term()

        while peek() in ("+", "-"):
            op = consume()[0]
            rhs = parse_term()

            if op == "+":
                value += rhs
            else:
                value -= rhs

        return value

    def parse_term():
        value = parse_factor()

        while peek() in ("*", "/"):
            op = consume()[0]
            rhs = parse_factor()

            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value /= rhs

        return value

    def parse_factor():
        if peek() == "+":
            consume("+")
            return +parse_factor()

        if peek() == "-":
            consume("-")
            return -parse_factor()

        return parse_atom()

    def parse_atom():
        if peek() == "NUM":
            return consume("NUM")[1]

        if peek() == "(":
            consume("(")
            value = parse_expression()

            if peek() != ")":
                raise ValueError("Missing closing parenthesis")

            consume(")")
            return value

        raise ValueError("Expected a number or '('")

    result = parse_expression()

    if pos != len(tokens):
        raise ValueError(f"Unexpected token {tokens[pos][0]!r}")

    return float(result)
