def is_match(s: str, p: str) -> bool:
    # dp[i][j] = True if s[:i] matches p[:j]
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Empty string vs patterns like a*, a*b*, ...
    for j in range(2, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            pc = p[j - 1]
            if pc == '*':
                # zero occurrences of the preceding element
                dp[i][j] = dp[i][j - 2]
                # one or more occurrences, if preceding element matches
                prev = p[j - 2]
                if prev == '.' or prev == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]
            elif pc == '.' or pc == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]
