def is_match(s, p):
    from functools import lru_cache

    n, m = len(s), len(p)

    @lru_cache(None)
    def dp(i, j):
        if j == m:
            return i == n

        first_match = i < n and (p[j] == s[i] or p[j] == '.')

        if j + 1 < m and p[j + 1] == '*':
            return dp(i, j + 2) or (first_match and dp(i + 1, j))

        return first_match and dp(i + 1, j + 1)

    return dp(0, 0)
```

