def is_match(s: str, p: str) -> bool:
    """
    Returns True if the string s matches the pattern p, where:
      '.' matches any single character
      '*' matches zero or more of the preceding element
    The match must cover the whole string.
    """
    m, n = len(s), len(p)

    # dp[i][j] = whether s[:i] matches p[:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Empty string can match patterns like a*, a*b*, .*, etc.
    for j in range(1, n + 1):
        if p[j - 1] == '*' and j >= 2:
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # Use zero occurrences of the preceding element
                if j >= 2:
                    dp[i][j] = dp[i][j - 2]

                # Use one or more occurrences if preceding element matches current char
                if j >= 2 and (p[j - 2] == '.' or p[j - 2] == s[i - 1]):
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

            elif p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]
