from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.cache = OrderedDict()  # keys ordered from least to most recently used

    def get(self, key):
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)  # mark as most recently used
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)  # update recency, then value
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)  # evict least recently used
```

- `get` and `put` are O(1) average time, since `OrderedDict` lookups, `move_to_end`, and `popitem` are all O(1).
- `move_to_end(key)` relocates a key to the back (most recently used).
- `popitem(last=False)` removes the front item (least recently used) when capacity is exceeded.

