def evaluate(expr):
    """
    Evaluate an arithmetic expression string containing integers,
    + - * /, parentheses and unary minus. Returns a float.

    Grammar (recursive descent):
        expr   := term (('+' | '-') term)*
        term   := factor (('*' | '/') factor)*
        factor := '-' factor | '+' factor | '(' expr ')' | number
        number := digit+ (optionally with a decimal point)
    """
    s = expr
    n = len(s)
    pos = 0  # current index; use a list-free approach with nonlocal

    def skip_whitespace():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    def parse_expr():
        nonlocal pos
        value = parse_term()
        while True:
            skip_whitespace()
            if pos < n and s[pos] in '+-':
                op = s[pos]
                pos += 1
                rhs = parse_term()
                if op == '+':
                    value += rhs
                else:
                    value -= rhs
            else:
                break
        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()
        while True:
            skip_whitespace()
            if pos < n and s[pos] in '*/':
                op = s[pos]
                pos += 1
                rhs = parse_factor()
                if op == '*':
                    value *= rhs
                else:
                    value /= rhs
            else:
                break
        return value

    def parse_factor():
        nonlocal pos
        skip_whitespace()
        if pos >= n:
            raise ValueError("Unexpected end of expression")

        # Unary minus / plus
        if s[pos] == '-':
            pos += 1
            return -parse_factor()
        if s[pos] == '+':
            pos += 1
            return parse_factor()

        # Parenthesized sub-expression
        if s[pos] == '(':
            pos += 1
            value = parse_expr()
            skip_whitespace()
            if pos >= n or s[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return value

        # Number (integer; decimal point accepted for robustness)
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        if pos < n and s[pos] == '.':
            pos += 1
            while pos < n and s[pos].isdigit():
                pos += 1
        if pos == start:
            raise ValueError(f"Unexpected character at position {pos}: {s[pos]!r}")
        return float(s[start:pos])

    result = parse_expr()
    skip_whitespace()
    if pos != n:
        raise ValueError(f"Unexpected character at position {pos}: {s[pos]!r}")
    return float(result)
```

