def evaluate(expr):
    """
    Evaluate an arithmetic expression string containing integers,
    + - * /, parentheses, and unary minus. Returns a float.

    Grammar (recursive descent):
        expr   := term  (('+' | '-') term)*
        term   := factor (('*' | '/') factor)*
        factor := ('+' | '-') factor | NUMBER | '(' expr ')'
    """
    s = expr
    n = len(s)
    pos = 0  # current index, kept in a mutable container via list

    def skip_ws(i):
        while i < n and s[i].isspace():
            i += 1
        return i

    def parse_expr(i):
        value, i = parse_term(i)
        while True:
            i = skip_ws(i)
            if i < n and s[i] in '+-':
                op = s[i]
                rhs, i = parse_term(i + 1)
                if op == '+':
                    value += rhs
                else:
                    value -= rhs
            else:
                return value, i

    def parse_term(i):
        value, i = parse_factor(i)
        while True:
            i = skip_ws(i)
            if i < n and s[i] in '*/':
                op = s[i]
                rhs, i = parse_factor(i + 1)
                if op == '*':
                    value *= rhs
                else:
                    if rhs == 0:
                        raise ZeroDivisionError("division by zero in expression")
                    value /= rhs
            else:
                return value, i

    def parse_factor(i):
        i = skip_ws(i)
        if i >= n:
            raise ValueError("unexpected end of expression")
        ch = s[i]
        if ch == '+':
            return parse_factor(i + 1)
        if ch == '-':
            value, i = parse_factor(i + 1)
            return -value, i
        if ch == '(':
            value, i = parse_expr(i + 1)
            i = skip_ws(i)
            if i >= n or s[i] != ')':
                raise ValueError("missing closing parenthesis")
            return value, i + 1
        # parse an integer literal
        start = i
        while i < n and s[i].isdigit():
            i += 1
        if start == i:
            raise ValueError(f"unexpected character {s[i]!r} at position {i}")
        return float(int(s[start:i])), i

    result, end = parse_expr(0)
    end = skip_ws(end)
    if end != n:
        raise ValueError(f"unexpected character {s[end]!r} at position {end}")
    return float(result)
```

