def evaluate(expr: str) -> float:
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # term (('+'|'-') term)*
        value = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        # factor (('*'|'/') factor)*
        value = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            rhs = parse_factor()
            if op == '*':
                value = value * rhs
            else:
                value = value / rhs
        return value

    def parse_factor():
        # unary '-' factor | '(' expr ')' | number
        tok = peek()
        if tok == '-':
            consume()
            return -parse_factor()
        if tok == '+':
            consume()
            return parse_factor()
        if tok == '(':
            consume()
            value = parse_expr()
            if consume() != ')':
                raise ValueError("Missing closing parenthesis")
            return value
        if tok is None:
            raise ValueError("Unexpected end of expression")
        consume()
        try:
            return float(tok)
        except ValueError:
            raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos]}")
    return result
```

This uses a recursive descent parser with the standard grammar `expr → term (± term)*`, `term → factor (*,/ factor)*`, `factor → number | (expr) | -factor`, giving correct precedence, left associativity, parentheses, and unary minus. Division uses true division, so results are floats.

