        nonlocal i
        value = parse_term()
        while True:
            skip_ws()
            if i < n and s[i] in "+-":
                op = s[i]
                i += 1
                rhs = parse_term()
                if op == "+":
                    value += rhs
                else:
                    value -= rhs
            else:
                return value

    def parse_term():
        nonlocal i
        value = parse_factor()
        while True:
            skip_ws()
            if i < n and s[i] in "*/":
                op = s[i]
                i += 1
                rhs = parse_factor()
                if op == "*":
                    value *= rhs
                else:
                    value /= rhs
            else:
                return value

    def parse_factor():
        nonlocal i
        skip_ws()
        if i < n and s[i] in "+-":
            op = s[i]
            i += 1
            value = parse_factor()
            return -value if op == "-" else value
        return parse_primary()

    def parse_primary():
        nonlocal i
        skip_ws()

        if i < n and s[i] == "(":
            i += 1
            value = parse_expr()
            skip_ws()
            if i >= n or s[i] != ")":
                raise ValueError("Mismatched parentheses")
            i += 1
            return value

        start = i
        while i < n and "0" <= s[i] <= "9":
            i += 1

        if start == i:
            if i < n:
                raise ValueError(f"Unexpected character at position {i}: {s[i]!r}")
            raise ValueError("Unexpected end of expression")

        return float(int(s[start:i]))

    skip_ws()
    if i >= n:
        raise ValueError("Empty expression")

    result = parse_expr()
    skip_ws()

    if i != n:
        raise ValueError(f"Unexpected character at position {i}: {s[i]!r}")

    return float(result)
