def evaluate(expr):
    """
    Evaluate an arithmetic expression with integers, + - * /, parentheses,
    and unary minus. Returns a float.
    """
    # --- Tokenizer ---------------------------------------------------------
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            # allow decimal numbers too, just in case
            if j < n and expr[j] == '.':
                j += 1
                while j < n and expr[j].isdigit():
                    j += 1
            tokens.append(expr[i:j])
            i = j
        elif ch in '+-*/()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError("Invalid character: %r" % ch)

    pos = 0  # current token index

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    # --- Recursive descent parser -----------------------------------------
    # expr   := term (('+' | '-') term)*
    # term   := factor (('*' | '/') factor)*
    # factor := '-' factor | primary
    # primary:= NUMBER | '(' expr ')'

    def parse_expr():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                value += rhs
            else:
                value -= rhs
        return value

    def parse_term():
        value = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                value *= rhs
            else:
                value /= rhs
        return value

    def parse_factor():
        tok = peek()
        if tok == '-':
            advance()
            return -parse_factor()
        if tok == '+':          # tolerate unary plus as well
            advance()
            return parse_factor()
        if tok == '(':
            advance()
            value = parse_expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            advance()
            return value
        if tok is None:
            raise ValueError("Unexpected end of expression")
        advance()
        try:
            return float(tok)
        except ValueError:
            raise ValueError("Invalid token: %r" % tok)

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected token: %r" % tokens[pos])
    return float(result)
