    i = 0

    def skip_ws():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def parse_expression():
        nonlocal i
        value = parse_term()
        while True:
            skip_ws()
            if i < n and s[i] in "+-":
                op = s[i]
                i += 1
                rhs = parse_term()
                if op == "+":
                    value += rhs
                else:
                    value -= rhs
            else:
                break
        return value

    def parse_term():
        nonlocal i
        value = parse_factor()
        while True:
            skip_ws()
            if i < n and s[i] in "*/":
                op = s[i]
                i += 1
                rhs = parse_factor()
                if op == "*":
                    value *= rhs
                else:
                    value /= rhs
            else:
                break
        return value

    def parse_factor():
        nonlocal i
        skip_ws()
        if i < n and s[i] == "-":
            i += 1
            return -parse_factor()
        if i < n and s[i] == "+":
            i += 1
            return parse_factor()
        return parse_primary()

    def parse_primary():
        nonlocal i
        skip_ws()
        if i >= n:
            raise ValueError("Unexpected end of expression")

        c = s[i]
        if c == "(":
            i += 1
            value = parse_expression()
            skip_ws()
            if i >= n or s[i] != ")":
                raise ValueError("Expected ')'")
            i += 1
            return value

        if c.isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return float(s[start:i])

        raise ValueError(f"Unexpected character: {c!r}")

    result = parse_expression()
    skip_ws()
    if i != n:
        raise ValueError("Unexpected trailing input")
    return float(result)
