def is_match(s: str, p: str) -> bool:
    # DP: dp[i][j] = does s[i:] match p[j:]
    memo = {}

    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if j == len(p):
            result = (i == len(s))
        elif i == len(s):
            result = (j + 1 < len(p) and p[j + 1] == '*' and dp(i, j + 2))
        elif p[j] == '.' or p[j] == s[i]:
            if j + 1 < len(p) and p[j + 1] == '*':
                result = dp(i, j + 2) or dp(i + 1, j)
            else:
                result = dp(i + 1, j + 1)
        else:
            result = (j + 1 < len(p) and p[j + 1] == '*') and dp(i, j + 2)
        memo[(i, j)] = result
        return result

    return dp(0, 0)
