        val = parse_term()
        while True:
            skip_ws()
            if pos < len(s) and s[pos] in ('+', '-'):
                op = s[pos]
                pos += 1
                rhs = parse_term()
                if op == '+':
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_term():
        val = parse_factor()
        while True:
            skip_ws()
            if pos < len(s) and s[pos] in ('*', '/'):
                op = s[pos]
                pos += 1
                rhs = parse_factor()
                if op == '*':
                    val *= rhs
                else:
                    val /= rhs
            else:
                break
        return val

    def parse_factor():
        skip_ws()
        if pos < len(s) and s[pos] in ('+', '-'):
            op = s[pos]
            pos += 1
            val = parse_factor()
            return val if op == '+' else -val
        return parse_primary()

    def parse_primary():
        nonlocal pos
        skip_ws()
        if pos >= len(s):
            raise ValueError("Unexpected end of expression")

        if s[pos] == '(':
            pos += 1
            val = parse_expression()
            skip_ws()
            if pos >= len(s) or s[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return val

        start = pos
        while pos < len(s) and '0' <= s[pos] <= '9':
            pos += 1

        if start == pos:
            raise ValueError(f"Invalid character {s[pos]!r} at position {pos}")

        return int(s[start:pos])

    skip_ws()
    if pos >= len(s):
        raise ValueError("Empty expression")

    result = parse_expression()

    skip_ws()
    if pos != len(s):
        raise ValueError(f"Unexpected character {s[pos]!r} at position {pos}")

    return float(result)
