import re

def evaluate(expr):
    tokens = re.findall(r'\d+\.?\d*|[+\-*/()]', expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            val = val * rhs if op == '*' else val / rhs
        return val

    def parse_factor():
        if peek() == '-':
            advance()
            return -parse_factor()
        if peek() == '+':
            advance()
            return parse_factor()
        if peek() == '(':
            advance()
            val = parse_expr()
            advance()  # ')'
            return val
        return float(advance())

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected token: %s" % peek())
    return result
