def evaluate(expr):
    """
    Evaluate an arithmetic expression containing integers, + - * /,
    parentheses, and unary minus, respecting normal precedence.
    Returns a float.
    """
    tokens = tokenize(expr)
    pos = 0  # use a mutable index holder

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expression():
        # expression := term (('+' | '-') term)*
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                value += rhs
            else:
                value -= rhs
        return value

    def parse_term():
        # term := factor (('*' | '/') factor)*
        value = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                value *= rhs
            else:
                value /= rhs
        return value

    def parse_factor():
        # factor := ('-'|'+') factor | '(' expression ')' | number
        tok = peek()
        if tok == '-':
            advance()
            return -parse_factor()
        if tok == '+':
            advance()
            return parse_factor()
        if tok == '(':
            advance()
            value = parse_expression()
            if peek() != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return value
        if isinstance(tok, float):
            advance()
            return tok
        raise ValueError(f"Unexpected token: {tok!r}")

    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            c = s[i]
            if c.isspace():
                i += 1
            elif c in '+-*/()':
                tokens.append(c)
                i += 1
            elif c.isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                # optional decimal part (allowed though spec says integers)
                if j < len(s) and s[j] == '.' and j + 1 < len(s) and s[j + 1].isdigit():
                    j += 1
                    while j < len(s) and s[j].isdigit():
                        j += 1
                    tokens.append(float(s[i:j]))
                else:
                    tokens.append(float(s[i:j]))
                i = j
            else:
                raise ValueError(f"Invalid character: {c!r}")
        return tokens

    result = parse_expression()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return float(result)
