def evaluate(expr):
    """
    Evaluate an arithmetic expression string containing integers, + - * /,
    parentheses, and unary minus. Returns a float.
    Grammar (recursive descent):
        expr   := term (('+' | '-') term)*
        term   := factor (('*' | '/') factor)*
        factor := ('+' | '-')* primary
        primary:= NUMBER | '(' expr ')'
    """
    tokens = tokenize(expr)
    pos = 0  # use a mutable index holder

    class ParserState:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def advance(self):
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok

    state = ParserState(tokens)

    def parse_expr():
        value = parse_term()
        while state.peek() in ('+', '-'):
            op = state.advance()
            rhs = parse_term()
            if op == '+':
                value += rhs
            else:
                value -= rhs
        return value

    def parse_term():
        value = parse_factor()
        while state.peek() in ('*', '/'):
            op = state.advance()
            rhs = parse_factor()
            if op == '*':
                value *= rhs
            else:
                value /= rhs  # raises ZeroDivisionError naturally
        return value

    def parse_factor():
        # unary plus/minus (may be repeated, e.g. --5)
        sign = 1.0
        while state.peek() in ('+', '-'):
            if state.advance() == '-':
                sign = -sign
        tok = state.peek()
        if tok is None:
            raise SyntaxError("Unexpected end of expression")
        if tok == '(':
            state.advance()
            value = parse_expr()
            if state.advance() != ')':
                raise SyntaxError("Missing closing parenthesis")
            return sign * value
        if isinstance(tok, float):
            state.advance()
            return sign * tok
        raise SyntaxError(f"Unexpected token: {tok!r}")

    result = parse_expr()
    if state.pos != len(tokens):
        raise SyntaxError(f"Unexpected token at position {state.pos}: {state.peek()!r}")
    return float(result)


def tokenize(expr):
