        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch in '+-*/()':
            tokens.append(ch)
            i += 1
        elif ch.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(float(expr[i:j]))
            i = j
        else:
            raise ValueError(f"Invalid character in expression: {ch!r}")
