def evaluate(expr):
    s = expr
    n = len(s)
    i = 0

    def skip_ws():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def parse_expression():
        nonlocal i
        value = parse_term()
        skip_ws()

        while i < n and s[i] in "+-":
            op = s[i]
            i += 1
            rhs = parse_term()
            if op == "+":
                value += rhs
            else:
                value -= rhs
            skip_ws()

        return value

    def parse_term():
        nonlocal i
        value = parse_factor()
        skip_ws()

        while i < n and s[i] in "*/":
            op = s[i]
            i += 1
            rhs = parse_factor()
            if op == "*":
                value *= rhs
            else:
                value /= rhs
            skip_ws()

        return value

    def parse_factor():
        nonlocal i
        skip_ws()

        if i >= n:
            raise ValueError("Invalid expression")

        if s[i] == "-":
            i += 1
            return -parse_factor()

        if s[i] == "+":
            i += 1
            return parse_factor()

        if s[i] == "(":
            i += 1
            value = parse_expression()
            skip_ws()
            if i >= n or s[i] != ")":
                raise ValueError("Unmatched parentheses")
            i += 1
            return value

        start = i
        while i < n and s[i].isdigit():
            i += 1

        if start == i:
            raise ValueError("Invalid expression")

        return int(s[start:i])

    result = parse_expression()
    skip_ws()

    if i != n:
        raise ValueError("Invalid expression")

    return float(result)
