def is_match(s: str, p: str) -> bool:
    """
    Returns True if the string s matches the pattern p, where:
      '.' matches any single character
      '*' matches zero or more of the preceding element
    The match must cover the entire string s.
    """
    m, n = len(s), len(p)

    # dp[i][j] will be True if s[:i] matches p[:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Handle patterns that can match an empty string, e.g. a*, a*b*, .*
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # Zero occurrences of the preceding character
                dp[i][j] = dp[i][j - 2]

                # One or more occurrences, if current s char matches preceding pattern char
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]
            else:
                # Regular character or '.'
                if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                    dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]
