import re

def evaluate(expr: str) -> float:
    """Evaluate arithmetic expression with + - * /, parentheses, unary minus.
    Returns float. Does not use eval/exec."""
    tokens = re.findall(r'\d+\.?\d*|\.\d+|[+\-*/()]', expr)
    if not tokens:
        raise ValueError("empty expression")
    pos = 0

    def current():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        pos += 1

    def parse_expression():
        value = parse_term()
        while current() in ('+', '-'):
            op = current()
            advance()
            rhs = parse_term()
            if op == '+':
                value += rhs
            else:
                value -= rhs
        return value

    def parse_term():
        value = parse_factor()
        while current() in ('*', '/'):
            op = current()
            advance()
            rhs = parse_factor()
            if op == '*':
                value *= rhs
            else:
                value /= rhs
        return value

    def parse_factor():
        tok = current()
        if tok == '-':
            advance()
            return -parse_factor()
        if tok == '+':
            advance()
            return parse_factor()
        if tok == '(':
            advance()
            value = parse_expression()
            if current() != ')':
                raise ValueError("missing closing parenthesis")
            advance()
            return value
        if tok is None:
            raise ValueError("unexpected end of expression")
        try:
            num = float(tok)
        except ValueError:
            raise ValueError(f"unexpected token: {tok}") from None
        advance()
        return num

    result = parse_expression()
    if pos != len(tokens):
        raise ValueError("unexpected trailing tokens")
    return result
