```python
def evaluate(expr):
    s = expr
    pos = 0

    def skip_ws():
        nonlocal pos
        while pos < len(s) and s[pos].isspace():
            pos += 1

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            skip_ws()
            if pos < len(s) and s[pos] in "+-":
                op = s[pos]
                pos += 1
                rhs = parse_term()
                if op == "+":
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            skip_ws()
            if pos < len(s) and s[pos] in "*/":
                op = s[pos]
                pos += 1
                rhs = parse_factor()
                if op == "*":
                    val *= rhs
                else:
                    val /= rhs
            else:
                break
        return val

    def parse_factor():
        nonlocal pos
        skip_ws()
        if pos >= len(s):
            raise ValueError("Unexpected end of expression")
        c = s[pos]
        if c == "+":
            pos += 1
            return parse_factor()
        if c == "-":
            pos += 1
            return -parse_factor()
        if c == "(":
            pos += 1
            val = parse_expr()
            skip_ws()
            if pos >= len(s) or s[pos] != ")":
                raise ValueError("Expected ')'")
            pos += 1
            return val
        return parse_number()

    def parse_number():
        nonlocal pos
        skip_ws()
        start = pos
        while pos < len(s) and s[pos].isdigit():
            pos += 1
        if start == pos:
            raise ValueError(f"Expected number at position {start}")
        return int(s[start:pos])

    result = parse_expr()
    skip_ws()
    if pos != len(s):
        raise ValueError("Unexpected trailing characters")
    return float(result)
